-- 3. Criar tabela tenant_lucena.transcricoes (nova tabela)
-- Aba "Atendimentos" da planilha = logs de análise de mensagens
-- Diferente da tabela "atendimentos" (sessões) — armazena transcrições
-- ══════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS tenant_lucena.transcricoes (
  id          BIGSERIAL PRIMARY KEY,
  timestamp   TIMESTAMPTZ DEFAULT NOW(),
  telefone    TEXT DEFAULT '',
  nome        TEXT DEFAULT '',
  intencao    TEXT DEFAULT '',
  sentimento  TEXT DEFAULT '',
  transcricao TEXT DEFAULT '',
  preview     TEXT DEFAULT ''
);


